function Dialog({title,onClose,children,drawer=false}:{title:string,onClose:()=>void,children:ReactNode,drawer?:boolean}){
 const ref=useRef<HTMLElement>(null);
 const closeRef=useRef(onClose);closeRef.current=onClose;
 useEffect(()=>{const previous=document.activeElement as HTMLElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.focus();function key(e:KeyboardEvent){const dialogs=document.querySelectorAll('[role=dialog]');if(dialogs[dialogs.length-1]!==ref.current)return;if(e.key==='Escape'){e.preventDefault();closeRef.current();}if(e.key==='Tab'){const nodes=Array.from(ref.current?.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),textarea,select,[tabindex="0"]')||[]) as HTMLElement[];const focusable=nodes.filter(n=>n.getClientRects().length>0);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(!focusable.includes(document.activeElement as HTMLElement)||document.activeElement===first)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(!focusable.includes(document.activeElement as HTMLElement)||document.activeElement===last)){e.preventDefault();first?.focus();}}}document.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);previous?.focus();};},[]);
 return <div className={'overlay '+(drawer?'drawer-overlay':'')} onClick={e=>{if(e.target===e.currentTarget)onClose()}}><section ref={ref} tabIndex={-1} className={drawer?'drawer':'modal'} role="dialog" aria-modal="true" aria-label={title}><button className="close icon-btn" onClick={onClose} aria-label="Fechar janela"><X size={22}/></button>{children}</section></div>;
}
