 async function upload(file:File){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3000000){notify('Escolha uma fotografia JPG, PNG ou WebP até 3 MB.');return;}BY(true);try{const base=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const r=await action({action:'upload',type:file.type,data:base});ED((p:any)=>({...p,image:r.url}));}catch(e:any){notify(e.message)}finally{BY(false)}}
 function editProduct(p?:any){window.location.assign(p?.id?'/gestao/produtos/'+p.id:'/gestao/produtos/novo');}
 function paymentMail(o:any){const lines=[`Olá, ${o.name}.`,'',`Relativamente ao pedido ${o.id.slice(0,8).toUpperCase()}, confirmamos os seguintes produtos:`,...o.items.map((i:any)=>`${i.qty} × ${i.name} — ${linePrice(i)}`),'',`Total de produtos: ${eur(o.total)}`,'Portes e valor final: [preencher antes de enviar]',`Entrega: ${o.delivery}`,settings.mbway?`MB WAY: ${settings.mbway}`:'',settings.iban?`IBAN: ${settings.iban}`:'','Prazo e outras informações: [preencher antes de enviar]','','Após efetuar o pagamento, responda a este e-mail.','Obrigado,','Espaço Solnatura'];return 'mailto:'+o.email+'?subject='+encodeURIComponent('Solnatura · Pedido '+o.id.slice(0,8).toUpperCase())+'&body='+encodeURIComponent(lines.filter(x=>x!==null).join('\n'));}
 function exportOrders(){const rows=[['Referência','Data','Nome','E-mail','Telefone','Estado','Receção','Total de produtos'],...(data.orders||[]).map((o:any)=>[o.id.slice(0,8).toUpperCase(),o.date,o.name,o.email,o.phone,o.status,o.delivery,o.total===null?'A confirmar':String(o.total)])];const csv='\uFEFF'+rows.map(r=>r.map((x:any)=>'"'+String(x).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pedidos-solnatura.csv';a.click();URL.revokeObjectURL(url);}
 const faq=[['Como escolho os produtos?','Explore as categorias, consulte a ficha de cada artigo e adicione as quantidades ao carrinho. Pode rever e alterar a seleção antes de enviar.'],['O que significa preço sob consulta?','O preço ainda não está publicado. Peça uma proposta para conhecer o valor e a disponibilidade. Não assume qualquer obrigação de compra ao enviar o pedido.'],['Que pagamentos são aceites?','Consulte as condições de pagamento. O valor total, incluindo eventuais portes, deve ser aceite antes de qualquer pagamento.'],['Como recebo os produtos?',settings.delivery||'Os produtos são enviados para a morada indicada. As zonas de envio, os portes e os prazos são apresentados antes da compra.'],['Posso devolver um produto?','Nas compras à distância, dispõe em regra de 14 dias após a receção para exercer a livre resolução. Existem exceções legais, nomeadamente para certos produtos perecíveis ou selados por razões de higiene. Consulte a página de devoluções.'],['Como obtenho ajuda?','Contacte a Solnatura e indique a referência do pedido, quando aplicável. Não envie dados bancários de acesso nem informações de saúde.']];
